css:
.print-format {
	font-family: "IBM Plex Sans", "Helvetica Neue", "Segoe UI", Arial, sans-serif;
	font-size: 9pt;
	color: #161616;
	border-radius: 0;
	border-top: 4px solid #0f62fe;
}

.print-heading {
	border-bottom: 2px solid #161616;
	padding-bottom: 8px;
	margin-bottom: 16px;
	color: #161616;
}

.print-heading h2 {
	font-size: 20pt;
	font-weight: 400;
	letter-spacing: 0;
}

.print-heading small {
	color: #525252;
	font-size: 9pt;
}

.print-format table.table {
	border-collapse: collapse;
}

.print-format table.table thead th {
	background-color: #e0e0e0;
	color: #161616;
	font-weight: 600;
	border: none;
	border-bottom: 2px solid #161616;
	text-transform: none;
	font-size: 9pt;
	padding: 8px;
}

.print-format table.table td {
	border: none;
	border-bottom: 1px solid #e0e0e0;
	padding: 8px;
	vertical-align: top;
}

.print-format .letter-head {
	margin-bottom: 24px;
}

.print-format .important .value {
	font-size: 11pt;
	font-weight: 600;
}

.print-format label {
	color: #525252;
	font-size: 8pt;
	font-weight: 400;
	letter-spacing: 0.32px;
	margin-bottom: 2px;
}

.print-format .section-break {
	border-bottom: 1px solid #e0e0e0;
	padding-bottom: 12px;
	margin-bottom: 12px;
}

.print-format .comment-block,
.print-format blockquote {
	border-left: 3px solid #0f62fe;
	padding-left: 12px;
	color: #525252;
}

.print-format .square-image,
.print-format .signature-img {
	border-radius: 0;
}

.print-format a {
	color: #0f62fe;
}

/* ERPNext's bundled print formats (Sales Order/Invoice, Purchase Order,
   Quotation, Delivery Note "with Item Image" and "Standard" variants) embed
   their own <style> block directly in the template HTML - hardcoded Inter
   font and 8-18px rounded tables/cards/images (the same pattern shows up in
   ERPNext's default Letter Head fixtures too). That markup renders inside
   .print-format but after anything the rest of this stylesheet controls, so
   none of it is reachable by class name alone. None of its radius or font
   declarations carry !important, and !important beats even inline styles
   regardless of source order, so a blanket reset here reliably squares and
   re-fonts every one of those formats - letterhead included - without
   touching ERPNext's own templates. */
.print-format,
.print-format *:not(pre):not(code):not(kbd):not(samp) {
	font-family: "IBM Plex Sans", "Helvetica Neue", "Segoe UI", Arial, sans-serif !important;
}

.print-format,
.print-format * {
	border-radius: 0 !important;
}

/* Known ERPNext invoice-template header/highlight fills, swapped for the
   same gray-20 tint used for table headers above. */
.print-format .highlight-bg,
.print-format .words-box,
.print-format thead.table-header,
.print-format table.items-table thead,
.print-format table.tax-table thead,
.print-format table.info-table thead {
	background-color: #e0e0e0 !important;
}
